<script setup>
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import CustomerNav from '../../components/CustomerNav.vue'
import { addToCart, rupiah, toggleWishlist } from '../../services/store'
import { db } from '../../firebase'
import { doc, getDoc } from 'firebase/firestore'
const route = useRoute(), product = ref(null), quantity = ref(1), tab = ref('description'), notice = ref('')
onMounted(async () => { const result = await getDoc(doc(db, 'products', route.params.id)); if (result.exists()) product.value = { id: result.id, ...result.data() } })
async function add() { for (let i = 0; i < quantity.value; i++) await addToCart(product.value); notice.value = `${product.value.name} ditambahkan ke cart.` }
</script>
<template><CustomerNav/><main v-if="product" class="container product-detail-shell"><RouterLink to="/customer/products" class="detail-back"><i class="bi bi-arrow-left"/> Back to menu</RouterLink><section class="detail-hero"><div class="detail-gallery"><div class="detail-main-image"><img :src="product.image || '/img/cookies.jpeg'" :alt="product.name"><button class="detail-favorite" @click="toggleWishlist(product)"><i class="bi bi-heart"/></button></div></div><div class="detail-info"><div class="detail-category-row"><span class="detail-category"><i class="bi bi-cookie"/> {{ product.category === 'sweet' ? 'Sweet Corner' : 'Savory Corner' }}</span><span class="detail-chip">{{product.category}}</span><span class="detail-chip">{{product.isActive === 'pre order' ? 'Pre Order' : 'Ready Stock'}}</span></div><h1>{{product.name}}</h1><div class="detail-price"><span v-if="product.discount" class="price-old">{{rupiah(product.price)}}</span>{{rupiah(product.price*(1-(product.discount||0)/100))}}<span v-if="product.discount" class="badge-discount">-{{product.discount}}%</span></div><div class="detail-metrics"><div><span>Weight</span><strong>{{product.detail?.weight || '-'}}</strong></div><div><span>Servings</span><strong>{{product.detail?.servings || '-'}}</strong></div><div><span>Category</span><strong>{{product.category}}</strong></div></div><div class="stock-summary"><div><span>Stock available</span><strong>{{product.stock ?? '-'}} item</strong></div><progress :value="product.stock || 0" :max="Math.max(product.stock || 1, 1)"/></div><div class="quantity-row"><span>Quantity</span><div class="quantity-control"><button @click="quantity=Math.max(1,quantity-1)">−</button><strong>{{quantity}}</strong><button @click="quantity=Math.min(5,quantity+1)">+</button></div><small>Max 5 per order</small></div><button class="detail-add-cart" :disabled="product.isActive === 'pre order' && product.stock === 0" @click="add"><i class="bi bi-cart-plus"/> Add to Cart</button><p v-if="notice" class="text-success mt-3">{{notice}}</p></div></section><section class="detail-tabs"><nav><button :class="{active:tab==='description'}" @click="tab='description'">Description</button><button :class="{active:tab==='ingredients'}" @click="tab='ingredients'">Ingredients</button><button :class="{active:tab==='reviews'}" @click="tab='reviews'">Reviews</button></nav><div v-if="tab==='description'" class="detail-tab-panel active"><p>{{product.detail?.fullDescription || product.description}}</p></div><div v-else-if="tab==='ingredients'" class="detail-tab-panel active"><div v-if="product.detail?.ingredients?.length" class="ingredient-list"><span v-for="item in product.detail.ingredients" :key="item"><i class="bi bi-leaf"/> {{item}}</span></div><p v-else>Informasi bahan belum tersedia.</p></div><div v-else class="detail-tab-panel active"><p>Belum ada review untuk produk ini.</p></div></section></main><main v-else class="reference-page">Produk tidak ditemukan.</main></template>
